@namespace sv_d089c54a93f449b2abed0d08813dcf1b.Components.Pages.Settings

<nav class="settings-sidebar">
    <h3 class="sidebar-title">Settings</h3>
    <ul class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <li class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_d089c54a93f449b2abed0d08813dcf1b.Components.Pages.Settings
@using sv_d089c54a93f449b2abed0d08813dcf1b.Services

<div class="profile-section">
    <h2>Profile Settings</h2>

    @if (_profile is not null)
    {
        <div class="profile-form">
            <div class="avatar-area">
                <div class="avatar-preview">
                    <img src="@_avatarUrl" alt="Avatar" />
                </div>
                <label>Avatar URL</label>
                <input type="text" @bind="_avatarUrl" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label>Display Name</label>
                <input type="text" @bind="_displayName" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label>Email</label>
                <input type="email" @bind="_email" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label>Bio</label>
                <textarea rows="4" @bind="_bio" @bind:event="oninput"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
                <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">✓ Profile saved successfully!</div>
            }
        </div>
    }
    else
    {
        <p class="loading">Loading profile...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        LoadFromProfile(_profile);
    }

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        if (_profile is not null)
        {
            LoadFromProfile(_profile);
        }
    }
}

@namespace sv_d089c54a93f449b2abed0d08813dcf1b.Components.Pages.Settings
@using sv_d089c54a93f449b2abed0d08813dcf1b.Services

<div class="notifications-section">
    <h2>Notification Preferences</h2>

    @if (_prefs is not null)
    {
        <div class="toggle-group">
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
                <p class="toggle-description">Receive email notifications for important updates</p>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
                <p class="toggle-description">Receive push notifications in your browser</p>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
                <p class="toggle-description">Get a weekly summary of activity</p>
            </div>
        </div>

        <div class="channels-section">
            <h3>Muted Channels</h3>
            <p class="section-description">Check channels you want to mute</p>
            <div class="channel-list">
                @foreach (var channel in _channels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">✓ Notification preferences saved!</div>
        }
    }
    else
    {
        <p class="loading">Loading notification preferences...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _channels = new();
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _channels = _prefs.MutedChannels;
        _mutedChannels = new HashSet<string>(_prefs.MutedChannels);
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_d089c54a93f449b2abed0d08813dcf1b.Components.Pages.Settings
@using sv_d089c54a93f449b2abed0d08813dcf1b.Services

<div class="change-password-panel">
    <div class="panel-header" @onclick="ToggleExpand">
        <h3>Change Password</h3>
        <span class="expand-icon">@(_expanded ? "▲" : "▼")</span>
    </div>

    @if (_expanded)
    {
        <div class="panel-body">
            <div class="form-group">
                <label>Current Password</label>
                <input type="password" @bind="_currentPassword" />
            </div>

            <div class="form-group">
                <label>New Password</label>
                <input type="password" @bind="_newPassword" />
            </div>

            <div class="form-group">
                <label>Confirm New Password</label>
                <input type="password" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="toast error">@_error</div>
            }

            @if (_showSuccess)
            {
                <div class="toast success">✓ Password updated successfully!</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePasswordAsync" disabled="@_updating">
                @(_updating ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _error = "";
    private bool _showSuccess;
    private bool _updating;

    private void ToggleExpand() => _expanded = !_expanded;

    private async Task UpdatePasswordAsync()
    {
        _error = "";
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _error = "Current password is required.";
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "New password is required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        _updating = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _updating = false;

        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_d089c54a93f449b2abed0d08813dcf1b.Components.Pages.Settings
@using sv_d089c54a93f449b2abed0d08813dcf1b.Services

<div class="active-sessions">
    <h3>Active Sessions</h3>
    <table class="sessions-table">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th>Action</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@FormatLastActive(session.LastActive)</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            <button class="btn btn-danger btn-sm"
                                    @onclick="() => RequestRevoke(session)">
                                Revoke
                            </button>
                        }
                        else
                        {
                            <span class="current-badge">Current</span>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>

    @if (_sessionToRevoke is not null)
    {
        <div class="confirm-dialog-overlay">
            <div class="confirm-dialog">
                <h4>Revoke Session?</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Yes, Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "session-1";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? _sessionToRevoke;

    private void RequestRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@namespace sv_d089c54a93f449b2abed0d08813dcf1b.Components.Pages.Settings
@using sv_d089c54a93f449b2abed0d08813dcf1b.Services

<div class="security-section">
    <h2>Security Settings</h2>

    @if (_security is not null)
    {
        <ChangePasswordPanel SettingsService="SettingsService" />

        <div class="two-factor-section">
            <h3>Two-Factor Authentication</h3>
            <div class="two-factor-toggle">
                <label class="toggle-label">
                    <input type="checkbox" checked="@_security.TwoFactorEnabled" disabled />
                    <span class="toggle-switch"></span>
                    Two-Factor Authentication
                </label>
