@namespace sv_d089c54a93f449b2abed0d08813dcf1b.Components.Pages.Settings
@using sv_d089c54a93f449b2abed0d08813dcf1b.Services

<div class="notifications-section">
    <h2>Notification Preferences</h2>

    @if (_prefs is not null)
    {
        <div class="toggle-group">
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
                <p class="toggle-description">Receive email notifications for important updates</p>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
                <p class="toggle-description">Receive push notifications in your browser</p>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
                <p class="toggle-description">Get a weekly summary of activity</p>
            </div>
        </div>

        <div class="channels-section">
            <h3>Muted Channels</h3>
            <p class="section-description">Check channels you want to mute</p>
            <div class="channel-list">
                @foreach (var channel in _channels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>
        </div>

